import{_ as o,o as t,c as a,a3 as n}from"./chunks/framework.DH50UWNB.js";const w=JSON.parse('{"title":"Workspaces and roles","description":"","frontmatter":{},"headers":[],"relativePath":"use/workspaces.md","filePath":"use/workspaces.md"}'),s={name:"use/workspaces.md"};function r(i,e,h,c,p,l){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="workspaces-and-roles" tabindex="-1">Workspaces and roles <a class="header-anchor" href="#workspaces-and-roles" aria-label="Permalink to &quot;Workspaces and roles&quot;">​</a></h1><p>A workspace holds projects and the people who work on them: everyone in a workspace sees its projects and their work. Your account starts with a personal workspace.</p><h2 id="your-workspaces" tabindex="-1">Your workspaces <a class="header-anchor" href="#your-workspaces" aria-label="Permalink to &quot;Your workspaces&quot;">​</a></h2><p>The project switcher in the header lists your projects grouped by workspace; picking a project opens its workspace. When you belong to more than one, <strong>New project</strong> asks which workspace the project goes in, starting from your personal one. <strong>Members</strong> shows who is in the current workspace.</p><p>You join another workspace when someone invites you to it. The web app has no screen to create a team workspace: whoever needs one creates it through the <a href="/wake-dist/docs/reference/api#workspaces">HTTP API</a>, and becomes its owner.</p><p>The free plan allows 3 people in all, however many installations you run; see <a href="/wake-dist/docs/run/sign-up#free-plan-accounts">Free plan accounts</a>.</p><h2 id="invite-people" tabindex="-1">Invite people <a class="header-anchor" href="#invite-people" aria-label="Permalink to &quot;Invite people&quot;">​</a></h2><p>An owner invites someone from <strong>Members</strong>:</p><ol><li>Choose the role and <strong>Create invitation link</strong>.</li><li>Copy the link, which looks like <code>&lt;your Wake URL&gt;/invite#wake_inv_...</code>, and send it to the person yourself. Wake sends no email, and shows the link only once. It works once and expires after 7 days.</li><li>The person opens it. With an account, they sign in, see the workspace, the role and who invited them, and choose <strong>Join</strong>. Without one, they choose <strong>Create one</strong> on the sign-in screen: the account they create, with email and password or a sign-in provider, joins the workspace at once and Wake opens it.</li></ol><p>On a server where sign-up needs an invitation, an invitation link is the only way to create an account; opening sign-up without one says so.</p><p>When the installation already has the 3 people the free plan allows, the new link comes with a warning: someone who already has an account on this installation can still join with it, but someone without one can create their account only after whoever runs the installation frees a place by disabling an account (see <a href="/wake-dist/docs/run/sign-up#free-plan-accounts">Free plan accounts</a>). The link keeps working until then, for its 7 days.</p><p>Pending invitations are listed under the members; <strong>Revoke</strong> cancels one. Members see the list but not the invite form.</p><p>Anyone holding an unused link can join, so revoke one sent to the wrong person. The part of the link after <code>#</code> never leaves the browser in an address, so it does not show up in server logs.</p><h2 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Can</th></tr></thead><tbody><tr><td><strong>Owner</strong></td><td>Everything a member can, plus manage members, roles and invitations, and read the audit log</td></tr><tr><td><strong>Member</strong></td><td>Work on the projects: claim and complete tasks, sync plans, attach evidence, create tokens</td></tr><tr><td><strong>Viewer</strong></td><td>Read everything: projects, tracking, the roadmap, versions and the members; change nothing</td></tr></tbody></table><p>An owner changes anyone&#39;s role from their row on <strong>Members</strong>, after a confirmation. The workspace always keeps one owner.</p><p>A viewer cannot claim or complete tasks, sync a plan, attach evidence, create tokens or approve a device sign-in. The CLI then prints:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>wake: you are a viewer in this workspace, which is read-only; ask an owner to make you a member</span></span></code></pre></div><p>Making someone a viewer revokes their tokens for the workspace. An owner who becomes a member or a viewer loses the pending invitations they created.</p><h2 id="remove-a-member" tabindex="-1">Remove a member <a class="header-anchor" href="#remove-a-member" aria-label="Permalink to &quot;Remove a member&quot;">​</a></h2><p><strong>Remove</strong> on a member&#39;s row takes them out at once and revokes their tokens and the pending invitations they created for the workspace. The last owner cannot be removed.</p>',21)])])}const k=o(s,[["render",r]]);export{w as __pageData,k as default};
